import { Diagnostic, path } from '@servicenow/sdk-build-core'
import { Project } from '../../src'

describe('Fluent Dependencies Test Suite', () => {
    test('GUIDs should be registered and wired up correctly across dependencies', async () => {
        const project = new Project({
            rootDir: path.resolve(__dirname, 'apps', 'b'),
        })

        const index = project.getFile('src/fluent/index.now.ts')
        expect(index).toBeDefined()

        const diagnostics = await index.getDiagnostics()
        const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
        expect(errors).toHaveLength(0)

        const records = await index.getRecords()
        expect(records.query()).toHaveLength(2)

        const role = records.get('sys_user_role', '28637d9cad6d43508dbe3e7bcaa7e50e')
        expect(role).toBeDefined()

        const contains = records.get('sys_user_role_contains', 'a090aa3028244502af3821c59040a6d8')
        expect(contains).toBeDefined()
        expect(contains.get('contains').toString().getValue()).toBe('371b314366e34ec59373582e981a6be3')

        const keys = project.getKeys().getValue()
        expect(Object.keys(keys.explicit)).toHaveLength(0)
        expect(Object.keys(keys.deleted)).toHaveLength(0)
        expect(keys.composite).toStrictEqual([
            {
                table: 'sys_user_role',
                id: '28637d9cad6d43508dbe3e7bcaa7e50e',
                key: { name: 'sn_app_b.role' },
            },
            {
                table: 'sys_user_role_contains',
                id: 'a090aa3028244502af3821c59040a6d8',
                key: {
                    role: '28637d9cad6d43508dbe3e7bcaa7e50e',
                    contains: '371b314366e34ec59373582e981a6be3',
                },
            },
        ])

        const dependentProject = new Project({
            rootDir: path.resolve(__dirname, 'apps', 'a'),
        })

        const dependentKeys = dependentProject.getKeys().getValue()
        expect(Object.keys(keys.explicit)).toHaveLength(0)
        expect(Object.keys(keys.deleted)).toHaveLength(0)
        expect(dependentKeys.composite).toStrictEqual([
            {
                table: 'sys_user_role',
                id: '371b314366e34ec59373582e981a6be3',
                key: { name: 'sn_app_a.role' },
            },
        ])
    })
})
